import random
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    n, e = map(int, lines[idx].split())
    idx += 1

    hate = set()
    for _ in range(e):
        u, v = map(int, lines[idx].split())
        idx += 1
        hate.add((min(u, v), max(u, v)))

    # Read trainers' wish lists
    wish_lists = []
    teams_used = set()
    T = 0

    for i in range(n):
        # Each team is numbered 1..T, so we need to count all unique teams
        if lines[idx] == '':
            idx += 1
            continue
        li = int(lines[idx])
        idx += 1
        teams = []
        for _ in range(li):
            teams.append(int(lines[idx]))
            idx += 1
        wish_lists.append(teams)
        T = max(T, max(teams))

    # We need to assign each trainer to a team from their wish list
    # and split the teams into 2 conferences such that at least e/2 hate pairs
    # have trainers from different conferences

    # Strategy: Try random assignments with expected value near e/2
    # If we assign teams randomly to conferences, expected hate between conferences
    # is e/2. With concentration, we should find valid assignments.

    def is_valid_assignment(trainer_teams, team_confs):
        hate_between = 0
        for (u, v) in hate:
            team_u = trainer_teams[u-1]
            team_v = trainer_teams[v-1]
            if team_u != team_v:
                conf_u = team_confs[team_u]
                conf_v = team_confs[team_v]
                if conf_u != conf_v:
                    hate_between += 1
        return hate_between * 2 >= e

    # Try random local searches
    for _ in range(100000):
        trainer_teams = [0] * (n + 1)

        # Randomly assign each trainer to a team from their wish list
        for i in range(n):
            wish = wish_lists[i]
            group = random.choice(wish)
            trainer_teams[i+1] = group

        # Randomly assign each team to a conference
        team_confs = {}
        for team in range(1, T+1):
            team_confs[team] = random.randint(1, 2)

        if is_valid_assignment(trainer_teams, team_confs):
            # Convert to 0-indexed for output
            trainer_teams_output = [str(trainer_teams[i]) for i in range(1, n+1)]
            team_confs_output = [str(team_confs[i]) for i in range(1, T+1)]
            return ' '.join(trainer_teams_output) + '\n' + ' '.join(team_confs_output)

    # If random strategy fails, try a different approach
    # Use a greedy randomized local search

    trainer_teams = [0] * (n + 1)
    for i in range(n):
        wish = wish_lists[i]
        # Prefer teams with fewer trainers to balance
        trainer_teams[i+1] = random.choice(wish)

    team_confs = {}
    for team in range(1, T+1):
        team_confs[team] = random.randint(1, 2)

    # Local search: try to improve hate count
    improved = True
    search_count = 0
    while improved and search_count < 200000:
        improved = False
        search_count += 1

        for i in range(n):
            u = i + 1
            current_team = trainer_teams[u]
            j = random.choice(range(1, n+1))
            v = j
            current_team_v = trainer_teams[v]

            # Try to move trainer to a different team
            new_team = random.choice(wish_lists[i])
            if new_team != current_team:
                trainer_teams[u] = new_team

                # Update team conferences if needed
                if new_team not in team_confs:
                    team_confs[new_team] = random.randint(1, 2)

                recalc = True

                # Count hate between different conferences
                hate_between = 0
                for (a, b) in hate:
                    ta = trainer_teams[a-1]
                    tb = trainer_teams[b-1]
                    if ta != tb and ta in team_confs and tb in team_confs:
                        if team_confs[ta] != team_confs[tb]:
                            hate_between += 1

                if hate_between * 2 >= e:
                    improved = True
                else:
                    trainer_teams[u] = current_team

        if improved and not is_valid_assignment(trainer_teams, team_confs):
            # Try different conference assignments
            for _ in range(100):
                team_confs = {}
                for team in range(1, T+1):
                    team_confs[team] = random.randint(1, 2)
                if is_valid_assignment(trainer_teams, team_confs):
                    return ' '.join([str(trainer_teams[i]) for i in range(1, n+1)]) + '\n' + ' '.join([str(team_confs[i]) for i in range(1, T+1)])

    # Final fallback: generate and check all options
    for _ in range(10000):
        trainer_teams = [0] * (n + 1)
        for i in range(n):
            trainer_teams[i+1] = random.choice(wish_lists[i])

        team_confs = {}
        for team in range(1, T+1):
            team_confs[team] = random.randint(1, 2)

        if is_valid_assignment(trainer_teams, team_confs):
            return ' '.join([str(trainer_teams[i]) for i in range(1, n+1)]) + '\n' + ' '.join([str(team_confs[i]) for i in range(1, T+1)])

    # Return last valid attempt
    trainer_teams_output = [str(trainer_teams[i]) for i in range(1, n+1)]
    team_confs_output = [str(team_confs[i]) for i in range(1, T+1)]
    return ' '.join(trainer_teams_output) + '\n' + ' '.join(team_confs_output)

