def get_prime_factors(n):
    """Get prime factorization of n as list of primes."""
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def gcd(a, b):
    """Compute GCD of a and b."""
    while b:
        a, b = b, a % b
    return a

def get_all_divisors(n):
    """Get all divisors of n that are greater than 1."""
    divs = {1}
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted([d for d in divs if d > 1])

def build_graph(divs, n):
    """Build adjacency map where edges exist if two numbers share a prime factor."""
    graph = {d: set() for d in divs}
    primes_at_num = {}

    # Group divisors by their prime factors
    for d in divs:
        pf = get_prime_factors(d)
        primes_at_num[d] = set(pf)

    # For each pair, if they share a prime factor, they're connected
    for i in range(len(divs)):
        for j in range(i + 1, len(divs)):
            d1, d2 = divs[i], divs[j]
            if primes_at_num[d1] & primes_at_num[d2]:
                graph[d1].add(d2)
                graph[d2].add(d1)

    return graph

