from collections import deque

class FlowGraph:
    def __init__(self, n):
        self.n = n
        self.capacity = {}
        self.flow = {}

    def add_edge(self, u, v, cap):
        self.capacity[(u, v)] = cap
        self.flow[(u, v)] = 0
        self.capacity[(v, u)] = 0
        self.flow[(v, u)] = 0
        self.graph = self.graph or []
        idx = len(self.graph)
        self.graph.append([v, cap, [(), ()]])

    def bfs(self, s, t):
        parent = {}
        visited = {s}
        queue = deque([s])

        while queue and t not in visited:
            u = popleft = queue.popleft()
            for v, cap_mpair in self.graph[u]:
                if (v not in visited) and cap_mpair[(u, v)] > 0:
                    visited.add(v)
                    parent[v] = u
                    queue.append(v)

        return parent

