import pytest

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    competitors = []
    for i in range(1, n + 1):
        s, r = map(int, lines[i].split())
        competitors.append((s, r, i))

    winners = set()

    for i in range(n):
        si, ri, idx_i = competitors[i]
        can_win = True

        for j in range(n):
            if i == j:
                continue
            sj, rj, _ = competitors[j]

            # Check if competitor j dominates competitor i
            if sj >= si and rj >= ri and (sj != si or rj != ri):
                can_win = False
                break

        if can_win:
            winners.add(idx_i)

    result = sorted(winners)
    return " ".join(map(str, result)) + "\n"

@pytest.mark.parametrize("input_str,expected", [
