def solution():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return "NO\n"

    idx = 0
    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1

    # For each variable, track which clauses contain it and its sign
    var_to_clauses = defaultdict(list)  # var -> [(var_index, clause_index, sign)]
    # For each clause, store its literals
    clauses = []

    for clause_idx in range(n):
        k = int(input_data[idx]); idx += 1
        literals = []
        for _ in range(k):
            lit = int(input_data[idx]); idx += 1
            # abs(lit) - 1 is the variable index (0-based)
            var = abs(lit) - 1
            sign = 1 if lit > 0 else -1
            literals.append((var, sign))
            var_to_clauses[var].append((clause_idx, sign))
        clauses.append(literals)

    # Track assignments: var -> 0 or 1 (unassigned if not set)
    assignment = [None] * m
    # Track if a variable is forced (from unit propagation)
    forced = set()

    # For clauses, track if they're satisfied
    satisfied = [False] * n
    # For each clause, track unassigned literals (for unit clause processing)
    unassigned_count = [len(clause) for clause in clauses]

    def resolve_clause(clause_idx):
        """Return list of satisfiable literals for this clause, or empty if all literals forced and clause unsatisfied"""
        result = []
        for var, sign in clauses[clause_idx]:
            val = assignment[var]
            if val is not None:
                if sign == 1 and val == 1:
                    satisfied[clause_idx] = True
                elif sign == -1 and val == 0:
                    satisfied[clause_idx] = True
            elif var in forced:
                val = 1 if forced[var] else 0
                if sign == 1 and val == 1:
                    satisfied[clause_idx] = True
                elif sign == -1 and val == 0:
                    satisfied[clause_idx] = True
        return result

    # Propagate unit clauses
    def propagate():
        changed = True
        while changed:
            changed = False
            for clause_idx in range(len(clauses)):
                if satisfied[clause_idx]:
                    continue
                # Check if this is a unit clause (only one unassigned literal)
                unassigned = []
                literal_vals = []
                for var, sign in clauses[clause_idx]:
                    if var not in forced and assignment[var] is None:
                        unassigned.append((var, sign))
                    else:
                        lit_val = 1 if assignment[var] == 1 else 0
                        lit_val = not lit_val if sign == -1 else lit_val
                        literal_vals.append(lit_val)

                # Count how many literals are already true in this clause
                true_count = sum(1 for val in literal_vals if val)

                if len(unassigned) == 1:
                    # This is a unit clause - the remaining literal must be true
                    var, sign = unassigned[0]
                    # The literal 'sign' must be true
                    # What does this mean for variable var?
                    if sign == 1:
                        assignment[var] = 1
                        forced.add(var)
                    else:
                        assignment[var] = 0
                        forced.add(var)
                    changed = True
                elif len(unassigned) > 1:
                    # This is a clause with multiple unassigned literals
                    # If all literals except one are forced to false, the last must be true
                    # (But we already used this logic for unit clauses)
                    pass

    propagate()

    # Check for conflicts
    for var in range(m):
        if assignment[var] == 0:
            if var in forced:
                continue
        if assignment[var] == 1:
            if var in forced:
                continue

    # Re-check propagation with forced variables
    propagate_forced = True
    while propagate_forced:
        propagate_forced = False
        for clause_idx in range(len(clauses)):
            if satisfied[clause_idx]:
                continue

            # Count satisfied literals
            cover = False
            unassigned = []
            for var, sign in clauses[clause_idx]:
                if var in assignment:
                    val = assignment[var]
                    if sign == 1 and val == 1:
                        cover = True
                        satisfied[clause_idx] = True
                    elif sign == -1 and val == 0:
                        cover = True
                        satisfied[clause_idx] = True
                elif var in forced:
