                    if sign == 1 and val == 1:
                        cover = True
                        satisfied[clause_idx] = True
                    elif sign == -1 and val == 0:
                        cover = True
                        satisfied[clause_idx] = True
                else:
                    unassigned.append((var, sign))

            if cover:
                continue

            if len(unassigned) == 1:
                var, sign = unassigned[0]
                if sign == 1:
                    if var not in forced:
                        assignment[var] = 1
                        forced.add(var)
                        propagate_forced = True
                else:
