def is_prime_direct(n):
    """Check if n is prime (for direct verification)"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(math.sqrt(n)) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True


def count_valid_primes(limit):
    """Count primes in [1, limit] where (p == 2 or p % 4 == 1)"""
    if limit < 2:
        return 0

    sqrt_limit = int(math.sqrt(limit)) + 1
    is_prime_small = [True] * sqrt_limit
    is_prime_small[0] = is_prime_small[1] = False

    primes = []
    for i in range(2, sqrt_limit):
        if is_prime_small[i]:
            primes.append(i)
            for j in range(i * i, sqrt_limit, i):
                is_prime_small[j] = False

    def is_prime_check(n, small_primes):
        if n < 2:
            return False
        if n <= sqrt_limit and not is_prime_small[n]:
            return False
        for p in small_primes:
            if p * p > n:
                break
            if n % p == 0:
                return False
        return True

    count = 0
    for i in range(2, limit + 1):
        if i > sqrt_limit:
            if not is_prime_check(i, primes):
                continue
        if is_prime_small[i] if i <= sqrt_limit else True:
            pass

        # Use Miller-Rabin for large numbers or precomputed sieve
        if is_prime_direct(i):
            if i == 2 or i % 4 == 1:
                count += 1

    return count

