def solution(input_str):
    n, l, r = map(int, input_str.strip().split())

    if n == 1:
        return str(r - l + 1)

    if n == 2:
        return str((r - l + 1) * (r - l))

    if n >= 4:
        return "0"

    if n == 3:
        sequences = set()

        # Count all valid 3-term geometric progressions where all elements are integers
        # For a, b, c to form a GP: b^2 = a * c, meaning b*b must be divisible by a
        for a in range(l, r + 1):
            for b in range(l, r + 1):
                if a == b:
                    continue
                if (b * b) % a == 0:
                    c = (b * b) // a
                    if l <= c <= r:
                        if c != a and c != b:
                            # Valid progression: a, b, c
                            sequences.add((a, b, c))
                            # Also count the reverse progression c, b, a
                            sequences.add((c, b, a))

        return str(len(sequences))

    return "0"

