    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    cell_cost = [[0] * m for _ in range(n)]

    for i in range(1, k + 1):
        sx, sy, d, t, e = map(int, lines[i].split())

        # The 4 positions in the cycle
        positions = [
            (sx, sy),
            (sx + d, sy - d),
            (sx + d, sy),
            (sx, sy + d)
        ]

        for step in range(4):
            bx, by = positions[step]
            base_time = t + step

            # This position occurs at times: base_time, base_time+4, base_time+8, ...
            # Blackout reaches (bx, by) at time bx + by
            # We need to check if bx + by >= base_time and (bx + by - base_time) % 4 == 0

            if 0 <= bx < n and 0 <= by < m:
                reach_time = bx + by
                if reach_time >= base_time:
                    cell_cost[bx][by] += e

    # DP to find minimum energy path
    dp = [[0] * m for _ in range(n)]

    # Starting position
    dp[0][0] = cell_cost[0][0]

    for x in range(n):
        for y in range(m):
            if x == 0 and y == 0:
                continue

            total_cost = cell_cost[x][y]

            if x == 0:
                dp[x][y] = dp[x][y-1] + total_cost
            elif y == 0:
                dp[x][y] = dp[x-1][y] + total_cost
            else:
                dp[x][y] = min(dp[x-1][y], dp[x][y-1]) + total_cost

    return str(dp[n-1][m-1]) + '\n'

