    dist = [INF] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]

    min_distances = [INF] * (n + 1)

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        if d < min_distances[u]:
            min_distances[u] = d

        for v, w in adj[u]:
            new_dist = dist[u] + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    used_train_count = 0
    ans = 0

    for s, y in train_routes:
        is_used = False

        if y == dist[s]:
            is_used = True

        for v, w in adj[s]:
            if v == 1:
                continue
            if dist[v] + w == dist[s]:
                if v in [1, s]:
                    pass
                if dist[v] + w == dist[s]:
                    is_used = True
                break

        if dist[s] > y:
            if is_used:
                pass
            else:
                ans += 1

    for s, y in train_routes:
