    edges = []
    for i in range(m):
        line = lines[2 + i]
        u, v = map(int, line.split())
        edges.append((u - 1, v - 1))

    def factorize(num):
        cnt = collections.defaultdict(int)
        d = 2
        while d * d <= num:
            if num % d == 0:
                count = 0
                while num % d == 0:
                    count += 1
                    num //= d
                cnt[d] = count
            d += 1
        if num > 1:
            cnt[num] = 1
        return cnt

    # Count prime factors for each position
    prime_data = collections.defaultdict(lambda: collections.defaultdict(int))
    for i in range(n):
        pf = factorize(a[i])
        for p, e in pf.items():
            prime_data[p][i] = max(prime_data[p][i], e)

    def max_flow(n_nodes, source, sink):
        """Simple DFS-based max flow"""
        ad = collections.defaultdict(list)  # adjacency: node -> [(neighbor, capacity)]
        flow = collections.defaultdict(int)

        def dfs(u, limited, path):
            if u == sink:
                return limited
            for v in ad[u]:
                cap = ad[u][v]
                if cap - flow[(u, v)] > 0 and v not in path:
                    path.append(v)
                    res = dfs(v, min(limited, ad[u][v] - flow[(u, v)]), path)
                    if res > 0:
                        flow[(u, v)] += res
                        flow[(v, u)] -= res
                        path.pop()
                        return res
            return 0

        maxf = 0
        while True:
            path = []
            res = dfs(source, float('inf'), path)
            if res == 0:
                break
            maxf += res
        return maxf

    total_ops = 0

    for p, positions in prime_data.items():
        # Odd indices (1-indexed, so odd numbers)
        odd_idx = [i for i in positions if (i + 1) % 2 == 1]
        # Even indices (1-indexed, so even numbers)
        even_idx = [i for i in positions if (i + 1) % 2 == 0]

        if not odd_idx or not even_idx:
            continue

        # Build bipartite graph
        num_nodes = 2 + len(odd_idx) + len(even_idx)
        source = num_nodes - 2
        sink = num_nodes - 1

        node_map = {source: 0, sink: 1}
        idx = 2
        for oi in odd_idx:
            node_map[oi] = idx
            idx += 1
        for ei in even_idx:
            node_map[ei] = idx
            idx += 1

        cap_mat = collections.defaultdict(int)

        # From source to odd indices
        for i in odd_idx:
            cap_mat[(source, node_map[i])] = prime_data[p][i]

        # From even indices to sink
        for i in even_idx:
            cap_mat[(node_map[i], sink)] = prime_data[p][i]

        # Edges between odd and even indices based on good pairs
        rev_edges = set()
        for u, v in edges:
            rev_edges.add((v, u))
            rev_edges.add((u, v))

        for u in odd_idx:
            for v in even_idx:
                if (u, v) in rev_edges:
                    cap_mat[(node_map[u], node_map[v])] = min(prime_data[p][u], prime_data[p][v])

        # Build adjacency for max flow
        adj = collections.defaultdict(list)
        for (u, v), cap in cap_mat.items():
            adj[u].append(v)
            adj[v]  # ensure reverse exists
        for u in adj:
            for v in list(adj[u]):
                cap_mat[(u, v)] += adj[v].count(u) if list(adj[v]).count(u) == 0 else cap_mat[(v, u)]

        total_ops += max_flow(num_nodes, source, sink)

    return str(total_ops) + '\n'

